#!/usr/bin/env python3
"""Reduce one release snapshot to the release desk's next-step receipt."""

import json
import sys


def _receipt(case_id, status, build, next_action, reason):
    return {
        "case_id": case_id,
        "status": status,
        "build": build,
        "next_action": next_action,
        "reason": reason,
        "action_performed": False,
    }


def _require_event_shape(event):
    if not isinstance(event, dict):
        raise ValueError("each event must be an object")
    for field in ("id", "release", "seq", "type"):
        if field not in event:
            raise ValueError("event is missing " + field)
    if not isinstance(event["seq"], int) or isinstance(event["seq"], bool):
        raise ValueError("event seq must be an integer")
    required = {
        "candidate": ("build",),
        "test": ("build", "outcome"),
        "approval": ("build", "actor"),
        "revoke": ("build", "actor"),
    }
    for field in required.get(event["type"], ()):
        if field not in event:
            raise ValueError("%s event is missing %s" % (event["type"], field))
    if event["type"] == "test" and event["outcome"] not in ("pass", "fail"):
        raise ValueError("test outcome must be pass or fail")


def prepare_receipt(snapshot):
    """Return the exact six-field desk receipt for a contract-valid snapshot."""
    if not isinstance(snapshot, dict):
        raise ValueError("snapshot must be an object")
    if "case_id" not in snapshot:
        raise ValueError("snapshot is missing case_id")
    case_id = snapshot["case_id"]
    owner = snapshot.get("owner")
    if not isinstance(owner, str) or not owner.strip():
        return _receipt(case_id, "needs_input", None, "request_input", "missing_owner")

    for field in ("release", "events"):
        if field not in snapshot:
            raise ValueError("snapshot is missing " + field)
    if not isinstance(snapshot["events"], list):
        raise ValueError("events must be an array")

    requested_release = snapshot["release"]
    events = []
    for event in snapshot["events"]:
        if not isinstance(event, dict):
            raise ValueError("each event must be an object")
        if "release" not in event:
            raise ValueError("event is missing release")
        if event["release"] != requested_release:
            continue
        _require_event_shape(event)
        events.append(event)

    # Release filtering intentionally precedes replay/conflict checks.
    by_id = {}
    for event in events:
        event_id = event["id"]
        if event_id in by_id:
            if event != by_id[event_id]:
                return _receipt(case_id, "needs_review", None, "review", "conflicting_event")
        else:
            by_id[event_id] = event
    events = list(by_id.values())

    seen_sequences = set()
    for event in events:
        if event["seq"] in seen_sequences:
            return _receipt(case_id, "needs_review", None, "review", "ambiguous_order")
        seen_sequences.add(event["seq"])
    events.sort(key=lambda event: event["seq"])

    candidates = [event for event in events if event["type"] == "candidate"]
    if not candidates:
        return _receipt(case_id, "needs_input", None, "request_input", "missing_candidate")
    candidate = candidates[-1]
    build = candidate["build"]

    tests = [
        event for event in events
        if event["type"] == "test"
        and event["build"] == build
        and event["seq"] > candidate["seq"]
    ]
    if not tests:
        return _receipt(case_id, "needs_input", build, "request_input", "missing_test")
    latest_test = tests[-1]
    if latest_test["outcome"] == "fail":
        return _receipt(case_id, "needs_review", build, "review", "tests_failed")

    authority_events = [
        event for event in events
        if event["type"] in ("approval", "revoke")
        and event["build"] == build
        and event["actor"] == owner
        and event["seq"] > latest_test["seq"]
    ]
    if not authority_events or authority_events[-1]["type"] != "approval":
        return _receipt(
            case_id, "needs_approval", build,
            "request_approval", "owner_approval_missing"
        )
    return _receipt(case_id, "completed", build, "ready", "ready")


def main(argv=None):
    argv = sys.argv if argv is None else argv
    if len(argv) != 3:
        raise SystemExit("usage: release_receipt.py INPUT.json OUTPUT.json")
    with open(argv[1], "r", encoding="utf-8") as source:
        snapshot = json.load(source)
    receipt = prepare_receipt(snapshot)
    with open(argv[2], "w", encoding="utf-8") as destination:
        json.dump(receipt, destination, separators=(",", ":"))
        destination.write("\n")


if __name__ == "__main__":
    main()

