import json
import unittest

from release_receipt import prepare_receipt


class ReleaseReceiptTests(unittest.TestCase):
    def test_supplied_examples(self):
        with open("dev_inputs.json", encoding="utf-8") as source:
            cases = json.load(source)
        self.assertEqual(
            prepare_receipt(cases[0]),
            {"case_id": "r-dev-pass", "status": "completed", "build": "b1",
             "next_action": "ready", "reason": "ready", "action_performed": False},
        )
        self.assertEqual(prepare_receipt(cases[1])["reason"], "tests_failed")

    def test_new_candidate_and_retest_invalidate_old_evidence(self):
        case = {
            "case_id": "reset", "release": "R", "owner": "Kim", "events": [
                {"id": "c1", "release": "R", "seq": 1, "type": "candidate", "build": "b1"},
                {"id": "t1", "release": "R", "seq": 2, "type": "test", "build": "b1", "outcome": "pass"},
                {"id": "a1", "release": "R", "seq": 3, "type": "approval", "build": "b1", "actor": "Kim"},
                {"id": "c2", "release": "R", "seq": 4, "type": "candidate", "build": "b1"},
                {"id": "t2", "release": "R", "seq": 5, "type": "test", "build": "b1", "outcome": "pass"},
            ],
        }
        self.assertEqual(prepare_receipt(case)["reason"], "owner_approval_missing")

    def test_current_build_failure_beats_stale_old_build_pass(self):
        case = {
            "case_id": "stale", "release": "R", "owner": "Kim", "events": [
                {"id": "old-pass", "release": "R", "seq": 4, "type": "test", "build": "old", "outcome": "pass"},
                {"id": "new-fail", "release": "R", "seq": 3, "type": "test", "build": "new", "outcome": "fail"},
                {"id": "new", "release": "R", "seq": 2, "type": "candidate", "build": "new"},
                {"id": "old", "release": "R", "seq": 1, "type": "candidate", "build": "old"},
            ],
        }
        receipt = prepare_receipt(case)
        self.assertEqual((receipt["build"], receipt["reason"]), ("new", "tests_failed"))

    def test_release_filter_replay_conflict_and_ambiguity(self):
        base = {"case_id": "x", "release": "R", "owner": "Kim"}
        foreign_conflict = [
            {"release": "OLD", "type": "candidate"},
            {"id": "z", "release": "OLD", "seq": 2, "type": "candidate", "build": "y"},
            {"id": "c", "release": "R", "seq": 1, "type": "candidate", "build": "b"},
        ]
        self.assertEqual(prepare_receipt(dict(base, events=foreign_conflict))["reason"], "missing_test")
        conflict = foreign_conflict[-1:] + [dict(foreign_conflict[-1], build="other")]
        self.assertEqual(prepare_receipt(dict(base, events=conflict))["reason"], "conflicting_event")
        ambiguous = foreign_conflict[-1:] + [
            {"id": "t", "release": "R", "seq": 1, "type": "test", "build": "b", "outcome": "pass"}
        ]
        self.assertEqual(prepare_receipt(dict(base, events=ambiguous))["reason"], "ambiguous_order")

    def test_revoke_then_fresh_approval(self):
        events = [
            {"id": "c", "release": "R", "seq": 1, "type": "candidate", "build": "b"},
            {"id": "t", "release": "R", "seq": 2, "type": "test", "build": "b", "outcome": "pass"},
            {"id": "a", "release": "R", "seq": 3, "type": "approval", "build": "b", "actor": "Kim"},
            {"id": "r", "release": "R", "seq": 4, "type": "revoke", "build": "b", "actor": "Kim"},
        ]
        case = {"case_id": "revoke", "release": "R", "owner": "Kim", "events": events}
        self.assertEqual(prepare_receipt(case)["reason"], "owner_approval_missing")
        events.append({"id": "a2", "release": "R", "seq": 5, "type": "approval", "build": "b", "actor": "Kim"})
        self.assertEqual(prepare_receipt(case)["reason"], "ready")


if __name__ == "__main__":
    unittest.main()
